diff --git a/src/queue.js b/src/queue.js
index a29f02f..c107d14 100644
--- a/src/queue.js
+++ b/src/queue.js
@@ -1,14 +1,33 @@
 import Bull from 'bull'
+import bullPackage from 'bull/package.json'

 /**
  * @type Queue = Bull.Queue
  */

-export const DEFAULT_QUEUE_OPTIONS = {}
+const bullMajorVersion = Number(bullPackage.version.split('.')[0])
+
+export const DEFAULT_QUEUE_OPTIONS = bullMajorVersion >= 4 ? {
+  redis: {
+    enableReadyCheck: false,
+    maxRetriesPerRequest: null,
+  },
+} : {}

 export const DEFAULT_JOB_OPTIONS = {
   attempts: 1,
 }

+const mergeQueueOptions = options => ({
+  ...DEFAULT_QUEUE_OPTIONS,
+  ...options,
+  ...(DEFAULT_QUEUE_OPTIONS.redis || options.redis ? {
+    redis: {
+      ...DEFAULT_QUEUE_OPTIONS.redis,
+      ...options.redis,
+    },
+  } : {}),
+})
+
 // createQueue :: (String, Object) -> Queue
-export default (redisDsn, options = {}) => new Bull('request-queue', redisDsn, { ...DEFAULT_QUEUE_OPTIONS, ...options })
+export default (redisDsn, options = {}) => new Bull('request-queue', redisDsn, mergeQueueOptions(options))
